#!/usr/bin/env node
/* Velora Core: turns core/tokens.json into two generated files.
   - core/velora-tokens.css : CSS custom properties (palettes, density, motion levels)
   - core/velora-tokens.js  : the same data for scripts (Studio, contrast audit)
   Usage: node scripts/build-tokens.mjs          write both files
          node scripts/build-tokens.mjs --check  exit 1 when the files are stale */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'core/tokens.json'), 'utf8'));
const kebab = s => String(s).replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
const HEADER = '/* GENERATED by scripts/build-tokens.mjs from core/tokens.json. Edit the JSON, then rebuild. */\n';

function block(selector, vars, indent = '  ') {
  return `${selector} {\n${vars.map(([k, v]) => `${indent}--vl-${k}: ${v};`).join('\n')}\n}\n`;
}

function paletteVars(p) {
  const v = [
    ['canvas-a', p.canvas.a], ['canvas-b', p.canvas.b], ['canvas-base', p.canvas.base],
    ['surface-rgb', p.surfaceRgb], ['surface-border', p.surfaceBorder], ['solid', p.solid],
    ['chip', p.chip], ['chip-border', p.chipBorder], ['track', p.track], ['line', p.line], ['line-strong', p.lineStrong],
    ['ink', p.ink], ['muted', p.muted], ['faint', p.faint], ['strong', p.strong], ['on-strong', p.onStrong],
    ['scrim', p.scrim], ['shadow-rgb', p.shadowRgb], ['focus', p.focus]
  ];
  for (const [k, c] of Object.entries(p.stage)) v.push([`stage-${k}`, c]);
  for (const [k, c] of Object.entries(p.status)) v.push([`status-${k}`, c]);
  p.chart.forEach((c, i) => v.push([`chart-${i + 1}`, c]));
  v.push(['chart-other', p.chartOther]);
  return v;
}

function css() {
  const b = tokens.base, pref = tokens.preferences;
  const base = [
    ['font-ui', b.font.ui], ['font-mono', b.font.mono],
    ...Object.entries(b.fontSize).map(([k, v]) => [`fs-${kebab(k)}`, v]),
    ...Object.entries(b.fontWeight).map(([k, v]) => [`fw-${k}`, v]),
    ...Object.entries(b.tracking).map(([k, v]) => [`tracking-${k}`, v]),
    ...Object.entries(b.space).map(([k, v]) => [`space-${k}`, v]),
    ['radius', `${pref.radius.default}px`], ['alpha', pref.alpha.default], ['blur', `${pref.blur.default}px`], ['text-scale', pref.textScale.default],
    ...Object.entries(b.radius).map(([k, v]) => [`r-${kebab(k)}`, v]),
    ...Object.entries(b.shadow).map(([k, v]) => [`shadow-${k}`, v]),
    ...Object.entries(b.ease).map(([k, v]) => [`ease-${kebab(k)}`, v]),
    ...Object.entries(b.layout).map(([k, v]) => [kebab(k), v]),
    ['surface', 'rgb(var(--vl-surface-rgb) / var(--vl-alpha))'],
    ['canvas', 'radial-gradient(75% 55% at 0% 0%, var(--vl-canvas-a), transparent 72%), radial-gradient(70% 60% at 100% 100%, var(--vl-canvas-b), transparent 72%), var(--vl-canvas-base)']
  ];
  const density = d => Object.entries(d).map(([k, v]) => [kebab(k), v]);
  const motion = m => Object.entries(m).map(([k, v]) => [`motion-${kebab(k)}`, v]);
  const pal = tokens.palettes;
  let out = HEADER;
  out += block(':root', [...base, ...paletteVars(pal.light), ...density(tokens.density.comfortable), ...motion(tokens.motion.signature)]);
  out += `:root { color-scheme: light; }\n`;
  for (const [name, p] of Object.entries(pal)) {
    out += block(`:root[data-vl-palette="${name}"]`, paletteVars(p)).replace('{\n', `{\n  color-scheme: ${p.scheme};\n`);
  }
  out += `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-vl-palette])', paletteVars(pal.dark), '  ').replace(/^/gm, '  ').replace('{\n', '{\n    color-scheme: dark;\n')}}\n`;
  for (const [name, d] of Object.entries(tokens.density)) out += block(`:root[data-vl-density="${name}"]`, density(d));
  for (const [name, m] of Object.entries(tokens.motion)) out += block(`:root[data-vl-motion="${name}"]`, motion(m));
  out += `@media (prefers-reduced-motion: reduce) {\n${block(':root:not([data-vl-motion])', motion(tokens.motion.reduced), '  ').replace(/^/gm, '  ')}}\n`;
  return out;
}

function js() {
  const data = {
    version: tokens.meta.version,
    palettes: Object.fromEntries(Object.entries(tokens.palettes).map(([k, p]) => [k, p])),
    preferences: tokens.preferences,
    density: tokens.density,
    motion: tokens.motion
  };
  return HEADER + `(function (g) {\n  g.Velora = g.Velora || {};\n  g.Velora.tokens = ${JSON.stringify(data, null, 2).replace(/\n/g, '\n  ')};\n})(typeof window !== 'undefined' ? window : globalThis);\n`;
}

const outputs = { 'core/velora-tokens.css': css(), 'core/velora-tokens.js': js() };
const check = process.argv.includes('--check');
let stale = [];
for (const [file, content] of Object.entries(outputs)) {
  const path = join(root, file);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : '';
  if (current === content) continue;
  if (check) stale.push(file); else writeFileSync(path, content);
}
if (check && stale.length) { console.error('Stale generated tokens: ' + stale.join(', ') + '. Run node scripts/build-tokens.mjs'); process.exit(1); }
console.log(check ? 'Velora tokens up to date' : 'Velora tokens built: ' + Object.keys(outputs).join(', '));
